// Typed client for the Pulse query API. Types come from the OpenAPI spec
// (src/generated/api.ts, regenerated by `make generate`).
import type { components, operations } from './generated/api';

export type Schemas = components['schemas'];
export type Trace = Schemas['Trace'];
export type SpanNode = Schemas['SpanNode'];
export type Issue = Schemas['Issue'];
export type IssueStatus = Schemas['IssueStatus'];
export type IssueList = Schemas['IssueList'];
export type IssueDetail = Schemas['IssueDetail'];
export type ErrorOccurrence = Schemas['ErrorOccurrence'];
export type ProductEvent = Schemas['ProductEvent'];
export type SpanEvent = Schemas['SpanEvent'];
export type TraceSummary = Schemas['TraceSummary'];
export type Me = Schemas['Me'];
export type Project = Schemas['Project'];
export type ApiKey = Schemas['ApiKey'];
export type CreatedProject = Schemas['CreatedProject'];
export type Org = Schemas['Org'];
export type Member = Schemas['Member'];
export type Invite = Schemas['Invite'];
export type InviteInfo = Schemas['InviteInfo'];
export type Role = Org['role'];
export type EventName = Schemas['EventName'];
export type FunnelQuery = Schemas['FunnelQuery'];
export type FunnelResult = Schemas['FunnelResult'];
export type FunnelStep = Schemas['FunnelStep'];
export type CohortHealth = Schemas['CohortHealth'];
export type FunnelError = Schemas['FunnelError'];
export type ListIssuesQuery = NonNullable<operations['listIssues']['parameters']['query']>;
export type ListTracesQuery = NonNullable<operations['listTraces']['parameters']['query']>;
export type ListEventsQuery = NonNullable<operations['listEvents']['parameters']['query']>;
type RangeQuery = { project_id?: number; from?: string; to?: string };

export class APIError extends Error {
  constructor(
    readonly status: number,
    message: string,
  ) {
    super(message);
  }
}

type Query = Record<string, string | number | undefined>;

export class APIClient {
  constructor(
    private readonly baseURL: string,
    private readonly fetchImpl: typeof fetch = (...a) => fetch(...a),
  ) {}

  /** Project used by data queries that do not name one. Unset means the API default (the first project). */
  project?: number;

  private async request<T>(method: string, path: string, query?: Query, body?: unknown): Promise<T> {
    const qs = new URLSearchParams();
    for (const [k, v] of Object.entries(query ?? {})) if (v !== undefined) qs.set(k, String(v));
    const scoped = !/^\/(health|v1\/auth\/|v1\/projects|v1\/orgs|v1\/invites)/.test(path);
    if (scoped && this.project !== undefined && !qs.has('project_id')) qs.set('project_id', String(this.project));
    const url = `${this.baseURL.replace(/\/$/, '')}${path}${qs.size ? `?${qs}` : ''}`;
    const res = await this.fetchImpl(url, {
      method,
      // The API rejects non-JSON mutations (CSRF protection), even bodiless ones.
      headers: method === 'GET' ? undefined : { 'Content-Type': 'application/json' },
      body: body === undefined ? undefined : JSON.stringify(body),
      credentials: 'same-origin',
    });
    if (!res.ok) {
      const err = (await res.json().catch(() => ({}))) as { error?: string };
      throw new APIError(res.status, err.error ?? res.statusText);
    }
    if (res.status === 204) return undefined as T;
    return (await res.json()) as T;
  }

  getHealth(): Promise<Schemas['Health']> {
    return this.request('GET', '/health');
  }

  login(email: string, password: string): Promise<Me> {
    return this.request('POST', '/v1/auth/login', undefined, { email, password });
  }

  signup(email: string, password: string, name: string, inviteToken?: string): Promise<Me> {
    return this.request('POST', '/v1/auth/signup', undefined, { email, password, name, invite_token: inviteToken });
  }

  requestPasswordReset(email: string): Promise<void> {
    return this.request('POST', '/v1/auth/password-reset/request', undefined, { email });
  }

  confirmPasswordReset(token: string, password: string): Promise<void> {
    return this.request('POST', '/v1/auth/password-reset/confirm', undefined, { token, password });
  }

  verifyEmail(token: string): Promise<void> {
    return this.request('POST', '/v1/auth/verify-email', undefined, { token });
  }

  resendVerification(): Promise<void> {
    return this.request('POST', '/v1/auth/verify-email/resend');
  }

  listMembers(orgId: number): Promise<Member[]> {
    return this.request('GET', `/v1/orgs/${orgId}/members`);
  }

  removeMember(orgId: number, userId: number): Promise<void> {
    return this.request('POST', `/v1/orgs/${orgId}/members/${userId}/remove`);
  }

  listInvites(orgId: number): Promise<Invite[]> {
    return this.request('GET', `/v1/orgs/${orgId}/invites`);
  }

  createInvite(orgId: number, email: string, role: Role): Promise<Invite> {
    return this.request('POST', `/v1/orgs/${orgId}/invites`, undefined, { email, role });
  }

  revokeInvite(orgId: number, inviteId: number): Promise<void> {
    return this.request('POST', `/v1/orgs/${orgId}/invites/${inviteId}/revoke`);
  }

  lookupInvite(token: string): Promise<InviteInfo> {
    return this.request('POST', '/v1/invites/lookup', undefined, { token });
  }

  acceptInvite(token: string): Promise<Me> {
    return this.request('POST', '/v1/invites/accept', undefined, { token });
  }

  logout(): Promise<void> {
    return this.request('POST', '/v1/auth/logout');
  }

  me(): Promise<Me> {
    return this.request('GET', '/v1/auth/me');
  }

  listKeys(projectId: number): Promise<ApiKey[]> {
    return this.request('GET', `/v1/projects/${projectId}/keys`);
  }

  rotateKey(projectId: number): Promise<ApiKey> {
    return this.request('POST', `/v1/projects/${projectId}/keys/rotate`);
  }

  createKey(projectId: number): Promise<ApiKey> {
    return this.request('POST', `/v1/projects/${projectId}/keys`);
  }

  revokeKey(projectId: number, keyId: number): Promise<ApiKey> {
    return this.request('POST', `/v1/projects/${projectId}/keys/${keyId}/revoke`);
  }

  listProjects(): Promise<Project[]> {
    return this.request('GET', '/v1/projects');
  }

  createProject(name: string, orgId?: number): Promise<CreatedProject> {
    return this.request('POST', '/v1/projects', undefined, { name, org_id: orgId });
  }

  renameProject(projectId: number, name: string): Promise<Project> {
    return this.request('PATCH', `/v1/projects/${projectId}`, undefined, { name });
  }

  listTraces(query: ListTracesQuery = {}): Promise<Schemas['TraceList']> {
    return this.request('GET', '/v1/traces', query as Query);
  }

  listServices(query: RangeQuery = {}): Promise<string[]> {
    return this.request('GET', '/v1/services', query);
  }

  listEvents(query: ListEventsQuery = {}): Promise<Schemas['EventList']> {
    return this.request('GET', '/v1/events', query as Query);
  }

  listEventNames(query: RangeQuery = {}): Promise<EventName[]> {
    return this.request('GET', '/v1/events/names', query);
  }

  queryFunnel(body: FunnelQuery, projectId?: number): Promise<FunnelResult> {
    return this.request('POST', '/v1/funnels/query', { project_id: projectId }, body);
  }

  getTrace(traceId: string, projectId?: number): Promise<Trace> {
    return this.request('GET', `/v1/traces/${encodeURIComponent(traceId)}`, { project_id: projectId });
  }

  listIssues(query: ListIssuesQuery = {}): Promise<IssueList> {
    return this.request('GET', '/v1/issues', query as Query);
  }

  getIssue(id: number, eventsLimit?: number): Promise<IssueDetail> {
    return this.request('GET', `/v1/issues/${id}`, { events_limit: eventsLimit });
  }

  updateIssue(id: number, status: IssueStatus): Promise<Issue> {
    return this.request('PATCH', `/v1/issues/${id}`, undefined, { status });
  }
}
